import React, { useState } from 'react';

import clsx from 'clsx';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getHikingSchedule } from '@apps/Hiking/@services/hikingSchedule.service';
import { getHikingScheduleResults } from '@apps/Hiking/@services/hikingScheduleResults.service';
import { IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';
import { IHikingScheduleResult } from '@apps/Hiking/@types/hikingScheduleResults.types';
import ScheduleItem from '@apps/Hiking/schedule/components/ScheduleItem';
import { showScheduleResultPreviewModal } from '@apps/Hiking/schedule/components/ScheduleResultPreviewModal/scheduleResultModalHelper';
import ScheduleResultStatus from '@apps/Hiking/schedule/components/ScheduleResultStatus';
import { routePartsModal } from '@apps/Routes/RoutePartModal/routePartModal';
import PageLoader from '@components/PageLoader';
import { declOfNum, formatDistance } from '@helpers/formatHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohCollapsible from '@ui-kit/Collapsible';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import DayInfoWidget from '../DayInfoWidget';
import HikingCollapsibleBlock from '../HikingCollapsibleBlock';

interface ICol {
  date: string;
  items: IHikingScheduleItem[];
  nd: number;
}

type ResultsRecords = Record<number, IHikingScheduleResult[]>;

const HikingSchedule: React.FC = () => {
  const [data, setData] = useState<ICol[][]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [err, setErr] = useState<Error>();

  const [scheduleItems, setScheduleItems] = useState<IHikingScheduleItem[]>([]);
  const [scheduleResults, setScheduleResults] = useState<ResultsRecords>({});

  const hikingData = React.useContext(HikingContext);

  const [before, setBefore] = useState<Record<string, IHikingScheduleItem[]>>();
  const [after, setAfter] = useState<Record<string, IHikingScheduleItem[]>>();

  const [filter, setFilter] = React.useState('all');

  React.useEffect(() => {
    const fetchData = async () => {
      if (!hikingData?.id) return;
      try {
        setIsLoading(true);
        const scheduleData = await getHikingSchedule(hikingData.id);
        setScheduleItems(scheduleData);

        const { start, finish } = hikingData;

        const daysObject: Record<string, IHikingScheduleItem[]> = {};
        const daysObjectBefore: Record<string, IHikingScheduleItem[]> = {};
        const daysObjectAfter: Record<string, IHikingScheduleItem[]> = {};

        let cur: string;
        const dS = start;
        const dF = finish;

        scheduleData.forEach((x) => {
          const d1 = x.start;
          const d2 = x.finish;

          const k1 = x.start.toLocaleDateString();

          if (d2 < dS) {
            if (!daysObjectBefore[k1]) {
              daysObjectBefore[k1] = [];
            }
            daysObjectBefore[k1].push(x);
          } else if (d1 > dF) {
            if (!daysObjectAfter[k1]) {
              daysObjectAfter[k1] = [];
            }
            daysObjectAfter[k1].push(x);
          } else {
            if (cur !== k1) {
              cur = k1;
              daysObject[k1] = [];
            }
            daysObject[k1].push(x);
          }
        });

        let cols: Array<ICol> = [];
        let dayNumber = 0;
        const rows: Array<ICol>[] = [];

        Object.keys(daysObject).forEach((k) => {
          cols.push({ date: k, items: daysObject[k], nd: dayNumber + 1 });
          dayNumber += 1;
          if (dayNumber % 2 === 0) {
            rows.push(cols);
            cols = [];
          }
        });

        if (dayNumber % 2 !== 0) {
          rows.push(cols);
        }

        setData(rows);
        if (Object.keys(daysObjectBefore).length) {
          setBefore(daysObjectBefore);
        }

        if (Object.keys(daysObjectAfter).length) {
          setAfter(daysObjectAfter);
        }

        const scheduleResultsData = await getHikingScheduleResults(hikingData.id);
        setScheduleResults(
          scheduleResultsData.reduce<ResultsRecords>((acc, x) => {
            if (!acc[x.id_hiking_schedule]) acc[x.id_hiking_schedule] = [];
            acc[x.id_hiking_schedule].push(x);
            return acc;
          }, {}),
        );
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [hikingData?.id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Warning}>{err.message}</PohAlert>;
  }

  const rows = data;

  const renderSchedule = (items: IHikingScheduleItem[]) => {
    return (
      <div className="mb-3">
        {items
          .filter(
            (item) =>
              filter === 'all' ||
              (filter === 'eat' && item.foodAct) ||
              (filter === 'route' && item.routeObject),
          )
          .map((scheduleItem, index) => {
            const timezoneForStart = hikingData?.timezones?.find(
              (tz) => tz.date_in <= scheduleItem.start && tz.date_out >= scheduleItem.start,
            );
            const timezoneForFinish = hikingData?.timezones?.find(
              (tz) => tz.date_in <= scheduleItem.finish && tz.date_out >= scheduleItem.finish,
            );

            return (
              <React.Fragment key={scheduleItem.id}>
                <ScheduleItem
                  id_hiking={hikingData!.id!}
                  scheduleItem={scheduleItem}
                  timezoneForStart={timezoneForStart}
                  timezoneForFinish={timezoneForFinish}
                  className={clsx(
                    index % 2 === 0 && 'bg-light',
                    index === items.length - 1 && 'border-bottom',
                  )}
                >
                  {scheduleResults[scheduleItem.id] &&
                    scheduleResults[scheduleItem.id].length > 0 && (
                      <div className="ps-3">
                        {scheduleResults[scheduleItem.id].map((res) => (
                          <ScheduleResultStatus
                            status={res.status}
                            key={res.id}
                            onClick={() =>
                              showScheduleResultPreviewModal({ scheduleItem, scheduleResult: res })
                            }
                          />
                        ))}
                      </div>
                    )}
                </ScheduleItem>
              </React.Fragment>
            );
          })}
      </div>
    );
  };

  if (!scheduleItems.length) return null;

  return (
    <HikingCollapsibleBlock
      id="schedule"
      header="План похода"
      count={scheduleItems.length}
      open
      toolbar={
        <small
          className="text-info ms-auto"
          style={{ fontSize: 12 }}
          onContextMenu={(e) => {
            e.preventDefault();
            setFilter((cur) => (cur === 'eat' ? 'all' : 'eat'));
          }}
          onClick={(e) => {
            e.stopPropagation();
            setFilter((cur) => (cur === 'route' ? 'all' : 'route'));
            e.preventDefault();
          }}
        >
          {filter === 'route' &&
            formatDistance(
              scheduleItems.reduce(
                (acc, item) =>
                  acc + (item.routeObject?.is_in_distance ? (item.routeObject?.distance ?? 0) : 0),
                0,
              ),
            )}
          {filter === 'eat' &&
            scheduleItems.reduce((acc, item) => acc + (item.foodAct ? 1 : 0), 0) + '\u2009раз'}
          {filter === 'all' && '\u00a0\u00a0.\u00a0\u00a0'}
        </small>
      }
    >
      {before && (
        <PohCollapsible
          open
          activatorComponent={
            <h4 className="text-muted">
              До похода ({Object.keys(before).length}&thinsp;
              {declOfNum(Object.keys(before).length, ['день', 'дня', 'дней'])})
            </h4>
          }
        >
          <PohRow>
            {Object.entries(before).map(([k, v], index, all) => (
              <PohCol key={k} sm={all.length < 2 ? 12 : Math.floor(12 / all.length)}>
                <header className={'d-flex justify-content-between'}>
                  <h6 className="text-muted">
                    До похода <small>#</small>
                    {index + 1}
                  </h6>
                  <DayInfoWidget date={v[0].start} className="ms-2 mb-1" />
                </header>
                {renderSchedule(v)}
              </PohCol>
            ))}
          </PohRow>
        </PohCollapsible>
      )}
      {rows.length > 0 && (
        <PohCollapsible
          open
          activatorComponent={
            <h4 className="text-muted">
              Основная часть похода ({rows.reduce((acc, val) => acc + val.length, 0)}&thinsp;
              {declOfNum(
                rows.reduce((acc, val) => acc + val.length, 0),
                ['день', 'дня', 'дней'],
              )}
              )
            </h4>
          }
        >
          {rows.map((row) => (
            <PohRow key={`row${row.map((x) => x.nd).join('-')}`}>
              {row.map((col) => (
                <PohCol key={col.nd} sm={row.length > 1 ? 6 : 12}>
                  <header className={'d-flex justify-content-between'}>
                    <h4>
                      День <small>#</small>
                      {col.nd}
                    </h4>
                    <DayInfoWidget date={col.items[0].start} className="ms-2 mb-1" />
                    <small
                      className="text-info ms-auto"
                      onClick={() => {
                        hikingData?.route.id &&
                          routePartsModal({
                            id_route: hikingData.route.id,
                            route_object_ids: col.items
                              .filter((x) => x.routeObject?.id)
                              .map((x) => x.routeObject!.id),
                          });
                      }}
                    >
                      {formatDistance(
                        col.items.reduce(
                          (acc, item) =>
                            acc +
                            (item.routeObject?.is_in_distance
                              ? (item.routeObject?.distance ?? 0)
                              : 0),
                          0,
                        ),
                      )}
                    </small>
                  </header>
                  {renderSchedule(col.items)}
                </PohCol>
              ))}
            </PohRow>
          ))}
        </PohCollapsible>
      )}
      {after && (
        <PohCollapsible
          open
          activatorComponent={
            <h4 className="text-muted">
              После похода ({Object.keys(after).length}&thinsp;
              {declOfNum(Object.keys(after).length, ['день', 'дня', 'дней'])})
            </h4>
          }
        >
          <PohRow>
            {Object.entries(after).map(([k, v], index, all) => (
              <PohCol key={k} sm={all.length < 2 ? 12 : Math.floor(12 / all.length)}>
                <header className={'d-flex justify-content-between'}>
                  <h6 className="text-muted">
                    После похода <small>#</small>
                    {index + 1}
                  </h6>
                  <DayInfoWidget date={v[0].start} className="ms-2 mb-1" />
                </header>
                {renderSchedule(v)}
              </PohCol>
            ))}
          </PohRow>
        </PohCollapsible>
      )}
    </HikingCollapsibleBlock>
  );
};

export default HikingSchedule;
