import React from 'react';

import { getInterviewsList } from '@apps/Interview/@services/interview.service';
import { IInterview } from '@apps/Interview/@types/interview.types';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

import InterviewListItem from '../InterviewListItem';

interface IInterviewListProps {
  onClick: (interview: IInterview, e: React.MouseEvent<Element, MouseEvent>) => void;
  id_hiking?: number;
}

const InterviewList: React.FC<IInterviewListProps> = ({ onClick, id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IInterview[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getInterviewsList(id_hiking ? { id_hiking } : {});
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_hiking]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <PohList
      flush
      data={data.map((interview) => {
        return {
          key: interview.id,
          action: true,
          onClick: (e) => {
            onClick(interview, e);
          },
          children: <InterviewListItem item={interview} />,
        };
      })}
    />
  );
};

export default InterviewList;

export const showInterviewListInModal = (
  data: IInterviewListProps & {
    title?: string;
  },
) => {
  showModal({
    title: data.title,
    children: <InterviewList {...data} />,
  });
};
