import React from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import clsx from 'clsx';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { useNavigate } from 'react-router-dom';

import { getHikingGpx } from '@apps/Hiking/@services/hikingResults.service';
import { IHikingGpx } from '@apps/Hiking/@types/hiking.types';
import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { downloadStringAsGpx, getGPXStringFromHikingGpx } from '@apps/Routes/@helpers/gpx.helper';
import { setMarkerObstacle, setMarkerStyles } from '@apps/Routes/@helpers/leaflet.helper';
import { setMarkerPass, setMarkerSimpleIcon } from '@apps/Routes/@helpers/routeObjects.helper';
import { getBaseRouteDataAsync, getRouteObjectsAsync } from '@apps/Routes/@services/routes.service';
import {
  IBaseRoute,
  IMapType,
  IRouteObject,
  RouteObjectType,
} from '@apps/Routes/@types/routes.types';
import RouteObjectIcon from '@apps/Routes/RouteEditorNew/components/RouteObjectIcon';
import { getColor } from '@helpers/colorsHelper';
import { formatDistance } from '@helpers/formatHelper';
import { getMap, quadkey } from '@helpers/leafletHelper';
import PohAlert from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import PohTabs, { IPohTab } from '@ui-kit/Tabs';

import style from './style.module.less';

const startIcon = L.divIcon({
  className: clsx(style.icon, style.iconStart),
  html: '',
  iconSize: [8, 8],
  iconAnchor: [4, 4],
});
const endIcon = L.divIcon({
  className: clsx(style.icon, style.iconEnd),
  html: '',
  iconSize: [8, 8],
  iconAnchor: [4, 4],
});

interface IHikingRouteCompletedProps {
  id_route: number;
  id_hiking: number;
}

const HikingRouteCompleted: React.FC<IHikingRouteCompletedProps> = ({ id_route, id_hiking }) => {
  const [mapData, setMapData] = React.useState<{
    routeData: IBaseRoute;
    typeData: IMapType;
  } | null>(null);
  const [routeObjectsData, setRouteObjectsData] = React.useState<IRouteObject[]>([]);
  const [gpxData, setGpxData] = React.useState<IHikingGpx[]>([]);
  const navigate = useNavigate();

  const [err, setErr] = React.useState<Error>();

  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const layerGroupRef = React.useRef<L.FeatureGroup>(L.featureGroup());
  const factGroupRef = React.useRef<L.FeatureGroup>(L.featureGroup());

  React.useEffect(() => {
    if (mapRef.current || !ref.current || !mapData || !routeObjectsData) {
      return;
    }

    if (!mapRef.current) {
      mapRef.current = getMap(ref.current as HTMLElement);

      L.tileLayer(
        mapData.typeData.tileUrlTmpl,
        L.Util.extend({ quadkey: quadkey }, mapData.typeData.id),
      ).addTo(mapRef.current);
      layerGroupRef.current.addTo(mapRef.current);
      factGroupRef.current.addTo(mapRef.current);
    }
    watermarkToMap(mapRef.current);

    layerGroupRef.current.clearLayers();

    if (mapData.routeData.bounds) mapRef.current.fitBounds(mapData.routeData.bounds);

    routeObjectsData.forEach((a) => {
      if (a.type === RouteObjectType.Point) {
        const pl = L.marker(a.coordinates);

        setMarkerSimpleIcon(pl, a.color);
        a.obstacle &&
          setMarkerPass(
            pl,
            {
              name: a.obstacle.name,
              altitude: a.obstacle.altitude,
              category: a.obstacle.category,
            },
            a.is_in_distance,
          );

        setMarkerStyles(pl, { color: a.color, opacity: a.is_in_distance ? 1 : 0.5 });
        if (a.obstacle) {
          setMarkerObstacle(pl, a.obstacle);
        }

        if (a.name.length) {
          pl.bindTooltip(`${a.name}\n${a.obstacle?.comment ?? ''}`);
        }
        if (a.description.length) {
          pl.bindPopup(a.description);
        }

        pl.addTo(layerGroupRef.current);
      } else if (a.type === RouteObjectType.Line) {
        const pl = new L.Polyline(a.points, {
          color: 'lime',
          weight: 3,
          opacity: 0.33,
          dashArray: +a.is_in_distance === 1 ? '' : '4,7',
        });

        pl.addTo(layerGroupRef.current);
      }
    });

    const bounds = layerGroupRef.current?.getBounds();
    if (bounds && bounds.isValid()) mapRef.current.fitBounds(bounds);
  }, [ref.current, mapData, routeObjectsData, gpxData]);

  React.useEffect(() => {
    if (!factGroupRef.current) return;
    if (!gpxData || !Array.isArray(gpxData)) return;

    factGroupRef.current.clearLayers();

    gpxData.forEach((track, index) => {
      if (!factGroupRef.current) return;
      const pl = new L.Polyline(
        track.track.map((p) => p.point),
        {
          color: getColor(index),
          weight: 4,
          opacity: 0.8,
          // dashArray:[5,5]
        },
      );
      pl.addTo(factGroupRef.current);

      new L.Marker(track.track[0].point, {
        icon: startIcon,
      }).addTo(factGroupRef.current);

      new L.Marker(track.track[track.track.length - 1].point, {
        icon: endIcon,
      }).addTo(factGroupRef.current);

      pl.bindTooltip(`${track.name}  ${formatDistance(+track.distance)}`);

      const gpxStr = getGPXStringFromHikingGpx(track, {
        dateStart: track.start,
        name: track.name,
        description: `${track.start.toLocaleString()} — ${track.finish.toLocaleString()}`,
        author: [track.author.name, track.author.surname].join(' '),
      });
      const bb = new Blob([gpxStr], { type: 'application/gpx+xml' });

      pl.bindPopup(`<b>${track.name}</b><br>
       Дистанция: <b>${formatDistance(track.distance)}</b>
       <br>${track.start.toLocaleString()} — ${track.finish.toLocaleString()}
       <br><a href="${window.URL.createObjectURL(bb)}" download="${track.name}.gpx">Скачать GPX</a>`);
      pl.addTo(factGroupRef.current);
    });
  }, [gpxData]);

  React.useEffect(() => {
    const getData = async () => {
      try {
        const [d1, d2, d3] = await Promise.all([
          getBaseRouteDataAsync(id_route),
          getRouteObjectsAsync(id_route),
          getHikingGpx(id_hiking),
        ]);
        setMapData(d1);
        setRouteObjectsData(d2);
        setGpxData(d3);
      } catch (e) {
        setErr(e as Error);
      }
    };

    getData();
  }, [id_route]);

  if (mapData == null || routeObjectsData == null) {
    return <PohLoader />;
  }

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  return (
    <PohRow className={style.hikingRoute}>
      <PohCol sm={9} ref={ref} className={style.oneHikingMapContainer} />
      <PohCol sm={3}>
        <PohTabs
          tabs={
            [
              gpxData?.length > 0 && {
                key: 'fact',
                title: (
                  <>
                    Пройдено &nbsp;
                    <PohBadge variant={BadgeVariant.Success}>
                      {formatDistance(gpxData.reduce((sum, cur) => sum + +cur.distance, 0))}
                    </PohBadge>
                  </>
                ),
                content: (
                  <div className={style.list}>
                    <PohList
                      data={gpxData.map((line, index) => {
                        const menu: Record<string, () => void> = {
                          ['Скачать GPX']: () => {
                            const gpxStr = getGPXStringFromHikingGpx(line, {
                              dateStart: line.start,
                              name: line.name,
                              description: `${line.start.toLocaleString()} — ${line.finish.toLocaleString()}`,
                              author: line.author.name + line.author.surname,
                            });
                            downloadStringAsGpx(gpxStr, line.name);
                          },
                          ['Подробнее']: () => {
                            navigate(`/hiking/${id_hiking}/tracks/${line.id}`);
                          },
                        };

                        return {
                          key: line.id,
                          action: true,
                          onClick: () => mapRef.current?.flyToBounds(line.bounds),
                          className: 'py-2 px-2 d-flex align-items-center justify-content-between',
                          style: { gap: 8 },
                          content: (
                            <>
                              <RouteObjectIcon
                                inDistance
                                color={getColor(index)}
                                type={RouteObjectType.Line}
                              />

                              <span
                                className="text-truncate flex-grow-1"
                                title={[
                                  line.name,
                                  line.start.toLocaleString(),
                                  line.finish.toLocaleString(),
                                ].join('\n')}
                              >
                                {line.name}
                              </span>
                              <span
                                className="ms-auto d-flex justify-content-end align-items-center flex-shrink-0"
                                style={{ gap: 6 }}
                              >
                                <b className="text-success">
                                  <small>{formatDistance(+line.distance)}</small>
                                </b>
                                <PohDropdown
                                  className="me-n2"
                                  onClick={(e) => e.stopPropagation()}
                                  menu={Object.entries(menu).map(([label, callback]) => {
                                    return (
                                      <button
                                        key={`menu-item-${label}`}
                                        className="dropdown-item"
                                        onClick={callback}
                                        type="button"
                                      >
                                        {label}
                                      </button>
                                    );
                                  })}
                                >
                                  <PohButton size={ButtonSize.Small} icon={true}>
                                    <ThreeDotsVertical />
                                  </PohButton>
                                </PohDropdown>
                              </span>
                            </>
                          ),
                        };
                      })}
                    />
                  </div>
                ),
              },
            ].filter(Boolean) as IPohTab[]
          }
        />
      </PohCol>
    </PohRow>
  );
};

export default HikingRouteCompleted;
