import React from 'react';

import { getHikingTextAsync } from '@apps/Hiking/@services/hiking.service';
import WysiwygViewer from '@components/WysiwygViewer';

import HikingCollapsibleBlock from '../HikingCollapsibleBlock';

interface IHikingTextProps {
  id_hiking: number;
}

const HikingText: React.FC<IHikingTextProps> = ({ id_hiking }) => {
  const [text, setText] = React.useState('');

  React.useEffect(() => {
    getHikingTextAsync(id_hiking).then(setText);
  }, [id_hiking]);

  if (!text) return null;

  return (
    <HikingCollapsibleBlock id="description" header="Описание" open>
      <WysiwygViewer>{text}</WysiwygViewer>
    </HikingCollapsibleBlock>
  );
};

export default HikingText;
