import { useState, useEffect } from 'react';

import { getHikingVacancies } from '@apps/Hiking/@services/hikingPositionsAndVacancies.service';
import { IHikingVacancy } from '@apps/Hiking/@types/hikingPositionsAndVacancies.types';
import PageLoader from '@components/PageLoader';
import PohList from '@ui-kit/List';

import Vacancy from './Vacancy';
import HikingCollapsibleBlock from '../HikingCollapsibleBlock';

function HikingVacancies({ id_hiking }: { id_hiking: number }) {
  const [data, setData] = useState<IHikingVacancy[] | null>(null);
  useEffect(() => {
    async function fetch() {
      const vacancies = await getHikingVacancies(id_hiking);
      setData(vacancies);
    }
    fetch();
  }, [id_hiking]);

  if (data == null) {
    return <PageLoader />;
  }

  if (!data?.length) {
    return null;
  }

  return (
    <HikingCollapsibleBlock
      id="vacancies"
      header="Помочь в организации похода"
      count={data.length}
      open
    >
      <PohList
        data={data.map((x) => ({
          key: x.id,
          className: 'list-group-item-action',
          content: <Vacancy data={x} id_hiking={id_hiking} />,
        }))}
      />
    </HikingCollapsibleBlock>
  );
}

export default HikingVacancies;
