import { useState, useEffect } from 'react';

import { getOnePosition } from '@apps/Hiking/@services/hikingPositionsAndVacancies.service';
import { IHikingPositionFull } from '@apps/Hiking/@types/hikingPositionsAndVacancies.types';
import PageLoader from '@components/PageLoader';
function OnePositionModalContent({ id_position }: { id_position: number }) {
  const [data, setData] = useState<IHikingPositionFull | null>(null);
  useEffect(() => {
    const fetch = async () => {
      const pos = await getOnePosition(id_position);
      setData(pos);
    };
    fetch();
  }, [id_position]);

  if (data == null) {
    return <PageLoader />;
  }

  return (
    <section>
      <h4>{data.name}</h4>
      <p>{data.description}</p>
      <h5>До похода</h5>
      <div className="mb-3" dangerouslySetInnerHTML={{ __html: data.desc_before }} />
      <h5>Во время похода</h5>
      <div className="mb-3" dangerouslySetInnerHTML={{ __html: data.desc_during }} />
      <h5>После похода</h5>
      <div className="mb-3" dangerouslySetInnerHTML={{ __html: data.desc_after }} />
    </section>
  );
}

export default OnePositionModalContent;
