import React from 'react';

import Binoculars from '@pohodnik/icons/svg/RealWorld/Binoculars';
import clsx from 'clsx';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { HikingAccessGroupContext } from '@apps/Hiking/@contexts/hikingPrivilegesContext';
import { HikingAccessGroup } from '@apps/Hiking/@types/hiking.rules';
import { IHiker } from '@apps/Hiking/@types/hiking.types';
import showModalAboutPositionAsync from '@apps/Hiking/positions/helpers/positionInfoHelper';
import { AuthContext } from '@contexts/AuthContext';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohButton from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohLink from '@ui-kit/Link';
import PohLoader, { LoaderVariant } from '@ui-kit/Loader';
import { showModal } from '@ui-kit/Modal';

import HikingMemberTimeEditModal from '../HikingMemberTimeEditModal';
import style from './style.module.less';

const handleClickOnPosition = (idPosition: number) => (event: React.MouseEvent) => {
  event.preventDefault();
  showModalAboutPositionAsync(idPosition);
};

const HikingMember: React.FC<IHiker & { equipSetId?: number }> = (hiker) => {
  const {
    idUser: id,
    name,
    surname,
    photo,
    positions,
    dateFrom = null,
    dateTo = null,
    isGirl,
    equipSetId,
  } = hiker;

  const hikingData = React.useContext(HikingContext);
  const authContext = React.useContext(AuthContext);
  const accessGroup = React.useContext(HikingAccessGroupContext);

  if (!hikingData) return null;

  const { start, finish } = hikingData;
  const fullDuration = finish.getTime() - start.getTime();
  const userDuration =
    (dateTo ? dateTo : finish).getTime() - (dateFrom ? dateFrom : start).getTime();

  const capacity = userDuration / fullDuration;
  const handleWarnClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    showModal({
      title: 'Редактирование времени участия в походе',
      children: (close: () => void) => (
        <HikingMemberTimeEditModal hiker={hiker} close={close} hikingData={hikingData} />
      ),
    });
  };

  return (
    <div
      className={clsx(
        'text-center animated p-3 m-1 toolbared',
        isGirl ? 'slideInRight' : 'slideInLeft',
        isGirl ? style.hikerGirl : style.hikerBoy,
        style.hiker,
      )}
    >
      <a href={`/user/${id}`} target="_blank" rel="noreferrer" className={style.avaContainer}>
        {(dateFrom || dateTo) && (
          <div
            className={clsx(style.sign, 'bg-light')}
            role="presentation"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();

              showModal({
                title: `Неполное участие в походе (${round(capacity * 100, 2)}%)`,
                children: (
                  <ul>
                    <li>{`С ${dateFrom ? dateFrom.toLocaleString() : 'начала'}`}</li>
                    <li>{`До ${dateTo ? dateTo.toLocaleString() : 'конца'}`}</li>
                  </ul>
                ),
              });
            }}
            title={`Неполное участие в походе (${round(capacity * 100, 2)}%)\n c ${dateFrom ? dateFrom.toLocaleString() : 'начала'} до ${dateTo ? dateTo.toLocaleString() : 'конца'}`}
          >
            <PohLoader
              variant={LoaderVariant.Danger}
              className="text-danger"
              value={capacity * 100}
              label={Math.round(capacity * 100)}
            />
          </div>
        )}
        {equipSetId && (
          <PohLink
            className={clsx(style.sharedEquipBtn, 'text-info')}
            href={`/hiking/${hikingData.id}/equip/${equipSetId}`}
            title="Заглянуть в рюкзак"
            onClick={(e) => {
              e.stopPropagation();
            }}
          >
            <Binoculars />
          </PohLink>
        )}
        {([HikingAccessGroup.Full, HikingAccessGroup.All, HikingAccessGroup.Boss].includes(
          accessGroup,
        ) ||
          authContext.user?.id === id) && (
          <aside
            className={clsx('show-on-hover position-absolute', style.paramsBtn)}
            onClick={(e) => {
              e.stopPropagation();
              e.preventDefault();
            }}
          >
            <PohButton icon={IconsEnum.cog} onClick={handleWarnClick} />
          </aside>
        )}
        <PohAva src={photo['100']} alt={[name, surname].join(' ')} width={100} />
        <div className={clsx('mt-2', style.hikerName)}>
          <strong>{name}</strong>
          <br />
          {surname}
        </div>
      </a>
      {authContext?.user && (
        <div className="mt-2">
          {positions &&
            positions.map((pos) => (
              <a
                key={pos.id}
                href={`#${pos.name}`}
                className="d-block text-truncate"
                onClick={handleClickOnPosition(pos.id)}
                title={`${pos.name} Утвердил ${pos.approver} ${pos.approve_date.toLocaleString()}`}
              >
                <small>{pos.name}</small>
              </a>
            ))}
        </div>
      )}
    </div>
  );
};

export default HikingMember;
