import React from 'react';

import GenderFemale from '@pohodnik/icons/svg/People/GenderFemale';
import GenderMale from '@pohodnik/icons/svg/People/GenderMale';
import People from '@pohodnik/icons/svg/People/People';
import { useNavigate } from 'react-router-dom';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getSharedEquipSets } from '@apps/Hiking/@services/equip.service';
import {
  getHikingUncompletedInterview,
  IHikingUncompletedInterview,
} from '@apps/Hiking/@services/hiking.service';
import { ISharedEquipSet } from '@apps/Hiking/@types/equip.types';
import { showInterviewListInModal } from '@apps/Interview/components/InterviewList';
import { showInterviewResultsInModal } from '@apps/Interview/components/InterviewResults';
import { runInterviewInModal } from '@apps/Interview/components/InterviewRun';
import { AuthContext } from '@contexts/AuthContext';
import { declOfNum } from '@helpers/formatHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import HikingCollapsibleBlock from '../HikingCollapsibleBlock';
import HikingMember from './components/HikingMember';

interface IMembersWidgetProps {
  isAllowJoin: boolean;
}

const MembersWidget: React.FC<IMembersWidgetProps> = ({ isAllowJoin }) => {
  const hikingData = React.useContext(HikingContext);
  const authData = React.useContext(AuthContext);

  const navigate = useNavigate();

  const [ivData, setIvData] = React.useState<IHikingUncompletedInterview[]>([]);
  const [shareEquipSetData, setShareEquipSetData] = React.useState<ISharedEquipSet[]>([]);

  const handleIvStart = (idIv: number) => () => {
    if (!hikingData) return;
    runInterviewInModal(idIv, undefined, () => window.location.reload());
  };

  React.useEffect(() => {
    if (!hikingData) return;
    getHikingUncompletedInterview(hikingData.id).then(setIvData);
  }, [hikingData]);

  React.useEffect(() => {
    if (!hikingData) return;
    if (!authData.isAuth) return;
    getSharedEquipSets(hikingData.id).then(setShareEquipSetData);
  }, [hikingData, authData]);

  if (!hikingData) return null;

  const { girlsCount, boysCount } = hikingData.hikers.reduce(
    (acc, val) => ({
      girlsCount: acc.girlsCount + +val.isGirl,
      boysCount: acc.boysCount + +!val.isGirl,
    }),
    { girlsCount: 0, boysCount: 0 },
  );

  const handleShowStat = () => {
    showInterviewListInModal({
      title: 'Просмотр статистики',
      id_hiking: hikingData.id,
      onClick: (iv) => showInterviewResultsInModal(iv.id, iv.name),
    });
  };

  const allow = React.useMemo(() => {
    let allow1 = true;
    if (hikingData.members_limit > 0) {
      allow1 = hikingData.members_limit < hikingData.hikers.length;
    }

    if (hikingData.allow_join_before) {
      allow1 = hikingData.allow_join_before > new Date();
    }

    return allow1;
  }, [hikingData.members_limit, hikingData.allow_join_before, hikingData.hikers.length]);

  return (
    <section className="border-top border-bottom bg-light mx-n2 px-2 mx-md-n5 px-md-5 py-1 mt-2 py-md-1 py-md-1 mt-md-5 mb-2 ">
      <HikingCollapsibleBlock
        open
        id="members"
        header="Участники"
        count={girlsCount + boysCount}
        toolbar={
          <>
            <div>
              <PohBadge variant={BadgeVariant.Light} rounded className="py-2 px-2 me-1">
                <People />
                &nbsp;
                {`${girlsCount + boysCount} ${declOfNum(girlsCount + boysCount, ['участник', 'участника', 'участников'])}`}
              </PohBadge>
              <PohBadge variant={BadgeVariant.Light} rounded className="py-2 px-2 me-1">
                <GenderMale /> {boysCount}
              </PohBadge>
              <PohBadge variant={BadgeVariant.Light} rounded className="py-2 px-2 me-3">
                <GenderFemale /> {girlsCount}
              </PohBadge>

              {!isAllowJoin && (
                <PohButton
                  variant={ButtonVariant.Light}
                  size={ButtonSize.Small}
                  icon={IconsEnum.chart}
                  onClick={handleShowStat}
                  title="Статистка опросов"
                />
              )}
            </div>
          </>
        }
      >
        {!isAllowJoin && ivData?.length > 0 && (
          <section>
            {ivData.map((iv) => (
              <PohAlert
                key={iv.id}
                variant={AlertVariant.Warning}
                className="d-flex align-items-center justify-content-between"
              >
                <div>
                  Вам необходимо заполнить анкету участника <strong>{iv.name}</strong>.
                </div>
                <PohButton onClick={handleIvStart(+iv.id)} variant={ButtonVariant.Danger}>
                  Начать
                </PohButton>
              </PohAlert>
            ))}
          </section>
        )}
        <PohRow>
          <PohCol sm={isAllowJoin ? 8 : 12} className="d-flex justify-content-center flex-wrap">
            {!hikingData.hikers.length && <Empty>Вы можете стать первым участником похода</Empty>}
            {hikingData.hikers.length > 0 &&
              hikingData.hikers.map((hiker) => (
                <HikingMember
                  key={hiker.idUser}
                  equipSetId={shareEquipSetData.find((d) => d.userFrom.id == hiker.idUser)?.id_set}
                  {...hiker}
                />
              ))}
          </PohCol>
          {isAllowJoin && (
            <PohCol sm={4}>
              <PohCard className="animated fadeIn" title="Вы можете присоединиться к походу">
                <div>
                  {hikingData.allow_join_before && (
                    <small className="text-muted d-block">
                      до {hikingData.allow_join_before.toLocaleString()}
                    </small>
                  )}
                  {hikingData.members_limit > 0 && (
                    <small className="text-muted d-block">
                      Осталось {hikingData.members_limit - hikingData.hikers.length}{' '}
                      {declOfNum(hikingData.members_limit - hikingData.hikers.length, [
                        'место',
                        'места',
                        'мест',
                      ])}
                    </small>
                  )}
                </div>
                <hr />
                <PohButton
                  variant={ButtonVariant.Primary}
                  size={ButtonSize.Big}
                  className="d-block w-100"
                  onClick={() => navigate(`/hiking/${hikingData?.id}/confirm`)}
                  disabled={!allow}
                >
                  Я пойду
                </PohButton>
              </PohCard>
            </PohCol>
          )}
        </PohRow>
      </HikingCollapsibleBlock>
    </section>
  );
};

