import React from 'react';

import { getHikingEquip } from '@apps/Hiking/@services/equip.service';
import { IHikingEquip } from '@apps/Hiking/@types/equip.types';
import HikingCollapsibleBlock from '@apps/Hiking/one/components/HikingCollapsibleBlock';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohCard from '@ui-kit/Card';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import EquipOptionsWidget from '../components/EquipOptionsWidget';
import { previewEquipModal } from '../previewEquip/previewEduipModal';
import EquipItem from './components/EquipItem';

type HikingEquipByUserMap = {
  [id_user: number]: {
    items: IHikingEquip[];
    totalWeight: 0;
    totalValue: 0;
    user: {
      id: number;
      name: string;
      photo: string;
    };
  };
};
const HikingPageEquipWidget = ({ id_hiking }: { id_hiking: number }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [data, setData] = React.useState<HikingEquipByUserMap>();

  React.useEffect(() => {
    getHikingEquip(id_hiking, true)
      .then((resp) => {
        setIsLoading(true);
        const mapedData = resp
          .sort((x) => (x.my ? 1 : -1))
          .reduce<HikingEquipByUserMap>((acc, val) => {
            if (!val.user) return acc;

            if (!acc[val.user.id]) {
              acc[val.user.id] = {
                items: [],
                totalWeight: 0,
                totalValue: 0,
                user: val.user,
              };
            }

            acc[val.user.id].items.push(val);

            if (val.isConfirm) {
              acc[val.user.id].totalValue += +val.value;
              acc[val.user.id].totalWeight += +val.weight;
            }

            return acc;
          }, {});

        setData(mapedData);
      })
      .finally(() => setIsLoading(false));
  }, []);

  const renderContent = () => {
    if (isLoading) {
      return <PageLoader />;
    }

    if (!data) {
      return null;
    }

    return (
      <>
        {Object.entries(data).map(([uid, userEquip]) => (
          <PohCol md={4} lg={3} key={uid}>
            <PohCard
              bodyClassName="p-0"
              className="mb-3"
              header={
                <div className="d-flex align-items-center justify-content-between">
                  <div className="d-flex align-items-center">
                    <PohAva
                      src={userEquip.user.photo}
                      alt={userEquip.user.name}
                      className="my-n2 ms-n2 me-2"
                    />
                    <strong>{userEquip.user.name}</strong>
                  </div>
                  <EquipOptionsWidget
                    value={round(userEquip.totalValue)}
                    weight={round(userEquip.totalWeight / 1000)}
                  />
                </div>
              }
            >
              <PohList
                flush
                data={userEquip.items.map((x) => ({
                  key: x.id,
                  className: 'list-group-item-action',
                  onClick: () => previewEquipModal(x, { footer: <></> }),
                  content: <EquipItem isConfirm={x.isConfirm} photo={x.photo} name={x.name} />,
                }))}
              />
            </PohCard>
          </PohCol>
        ))}
      </>
    );
  };

  return (
    <HikingCollapsibleBlock id="shared-equip" header="Общее снаряжение" open>
      <p>
        Данный раздел необходим для учета группового и общего снаряжения. {}
        Добавить свое можно в разделе{' '}
        <a href={`/hiking/${id_hiking}/equip`} target="_blank" rel="noreferrer">
          собрать рюкзак
        </a>{' '}
        (групповое).
        <br />
        Утверждаться (учитываться в нагрузке) будет только то снаряжение, которое является
        практически полезным и имеет общественное назначение. Например: топоры, пилы, котелки,
        палатки, тенты и т.п., остальное можно брать на своё усмотрение
      </p>
      <PohRow>{renderContent()}</PohRow>
    </HikingCollapsibleBlock>
  );
};

export default HikingPageEquipWidget;
