import React from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import Calendar2Plus from '@pohodnik/icons/svg/DateTime/Calendar2Plus';
import Compass from '@pohodnik/icons/svg/Geo/Compass';
import GeoAlt from '@pohodnik/icons/svg/Geo/GeoAlt';
import clsx from 'clsx';
import { useNavigate } from 'react-router-dom';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import CountDownTimer from '@components/CountdownTimer';
import PohAva from '@ui-kit/Ava';
import PohDropdown from '@ui-kit/Dropdown';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohLink from '@ui-kit/Link';

import { qrGenerate } from './qrHelper';
import styles from './styles.module.less';

const HeaderWidget = () => {
  const hikingData = React.useContext(HikingContext);
  const navigate = useNavigate();
  if (!hikingData) return <>Has no hikingData</>;

  const style = {
    backgroundColor: hikingData.visual.color,
    backgroundImage: hikingData?.visual?.bg?.length ? `url(${hikingData.visual.bg})` : '',
  };

  const handleShowQrCode = () => {
    qrGenerate(hikingData);
  };

  const needShowToStart = +hikingData.start > new Date().getTime();
  const needShowToFinish = !needShowToStart && +hikingData.finish > new Date().getTime();

  const actions = [];

  if (hikingData.route.id) {
    actions.push({
      name: 'Маршрут',
      action: () => navigate(`/routes/${hikingData.route.id}`),
    });
    actions.push({
      name: 'План прохождения маршрута',
      action: () => navigate(`/hiking/${hikingData.id}/hiking_route_info/${hikingData.route.id}`),
    });
  }
  actions.push({
    name: 'Моё снаряжение',
    action: () => navigate(`/hiking/${hikingData.id}/equip`),
  });
  actions.push({
    name: 'Снаряжение других участников',
    action: () => navigate(`/hiking/${hikingData.id}/equip/shared`),
  });

  actions.push({
    name: 'Моя страничка о походе 😎',
    action: () => navigate(`/hiking/${hikingData.id}/my/`),
  });

  actions.push({
    name: 'Записки',
    action: () => navigate(`/hiking/${hikingData.id}/obstacle_notes`),
  });

  actions.push({
    name: 'Список покупок',
    action: () => navigate(`/hiking/${hikingData.id}/shopping`),
  });
  actions.push({
    name: 'Тренировки',
    action: () => navigate(`/hiking/${hikingData.id}/workouts`),
  });

  actions.push({
    name: 'Треки',
    action: () => navigate(`/hiking/${hikingData.id}/tracks`),
  });
  actions.push({
    name: 'Финансы',
    action: () => navigate(`/hiking/${hikingData.id}/finance`),
  });
  actions.push({
    name: 'Меню',
    action: () => navigate(`/hiking/${hikingData.id}/menu`),
  });
  actions.push({
    name: 'Меню1',
    action: () => navigate(`/hiking/${hikingData.id}/menu1`),
  });
  actions.push({
    name: 'Меню2',
    action: () => navigate(`/hiking/${hikingData.id}/menu2`),
  });
  actions.push({
    name: 'Меню блюда',
    action: () => navigate(`/hiking/${hikingData.id}/menu/dishes`),
  });
  actions.push({
    name: 'Меню акты',
    action: () => navigate(`/hiking/${hikingData.id}/menu/acts`),
  });

  actions.push({
    name: 'Матрица провизии',
    action: () => navigate(`/hiking/${hikingData.id}/menu/matrix`),
  });
  actions.push({
    name: 'Печать меню',
    action: () => navigate(`/hiking/${hikingData.id}/menu/print1`),
  });
  actions.push({
    name: 'Печать наклеек',
    action: () => navigate(`/hiking/${hikingData.id}/menu/stickers`),
  });
  actions.push({
    name: 'Результаты',
    action: () => navigate(`/hiking/${hikingData.id}/results`),
  });
  actions.push({
    name: 'Печать',
    action: () => navigate(`/hiking/${hikingData.id}/print`),
  });
  actions.push({
    name: 'Дежурства',
    action: () => navigate(`/hiking/${hikingData.id}/duty`),
  });
  actions.push({
    name: 'Часовые пояса',
    action: () => navigate(`/hiking/${hikingData.id}/timezones`),
  });
  actions.push({
    name: 'Печать побаловаться',
    action: () => navigate(`/print/h${hikingData.id}`),
  });

  actions.push({
    name: 'Аптечка',
    action: () => navigate(`/hiking/${hikingData.id}/fak`),
  });

  actions.push({
    name: 'Ремнабор',
    action: () => navigate(`/hiking/${hikingData.id}/repair-kit`),
  });

  actions.push({
    name: 'Статьи',
    action: () => navigate(`/hiking/${hikingData.id}/articles`),
  });

  return (
    <>
      <div id="hikingHeader" style={style} className={clsx(styles.header, 'mx-n3 mx-md-n5')}>
        <div className={styles.divider}></div>
      </div>
      <PohRow className={styles.subheader}>
        <PohCol sm={2}>
          <PohAva
            src={hikingData.visual.photo}
            className={clsx(styles.ava, 'mt-n4')}
            alt={hikingData.name}
          />
        </PohCol>
        <PohCol sm={8} className="d-flex flex-column justify-content-end">
          <h1 className={clsx('mt-3', styles.title)}>{hikingData.name}</h1>
          <em className={clsx(styles.description, 'mt-n1 mb-1')}>{hikingData.desc}</em>
          <small className="d-flex align-items-center text-muted mb-2">
            <Compass className="text-muted" />
            &nbsp;{hikingData.type.name}
            {` \u00a0 `}
            <GeoAlt className="text-muted" />
            &nbsp;{hikingData.region.name}
          </small>
          <div className="d-flex align-items-center">
            <span>
              {hikingData.start.toLocaleString('default', {
                dateStyle: 'short',
                timeStyle: 'short',
              })}
            </span>
            &nbsp;—&nbsp;
            <span>
              {hikingData.finish.toLocaleString('default', {
                dateStyle: 'short',
                timeStyle: 'short',
              })}
            </span>
            <PohLink
              onClick={handleShowQrCode}
              title="Создать запись в календаре с помощью QR-кода"
            >
              <Calendar2Plus className="text-muted ms-2" />
            </PohLink>
          </div>

          <div className="hiking-header-date-left text-nowrap text-muted mt-lg-n1">
            {needShowToStart && (
              <>
                до старта: <CountDownTimer targetDate={hikingData.start} withSeconds />
              </>
            )}
            {needShowToFinish && (
              <>
                до завершения: <CountDownTimer targetDate={hikingData.finish} withSeconds />
              </>
            )}
          </div>

          {hikingData.slogan && (
            <em
              className="text-success border-start ps-2 mt-3"
              title="Фраза похода"
              style={{ fontSize: '13px' }}
            >
              {hikingData.slogan}
            </em>
          )}
        </PohCol>
        <PohCol sm={2} className="d-flex flex-column justify-content-end align-items-end text-end">
          <PohDropdown
            className="me-n2"
            menu={actions.map((x) => {
              return (
                <button key={x.name} className="dropdown-item" onClick={x.action} type="button">
                  {x.name}
                </button>
              );
            })}
          >
            <ThreeDotsVertical />
          </PohDropdown>
        </PohCol>
      </PohRow>
    </>
  );
};

export default HeaderWidget;
