import React, { FormEvent } from 'react';

import { IUncompletedUserRadish } from '@apps/Hiking/@services/hikingRadish.service';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import { showModal } from '@ui-kit/Modal';

interface IRadishUncompletedProps {
  data: IUncompletedUserRadish;
  onComplete: (comment: string) => void;
}

const RadishUncompleted: React.FC<IRadishUncompletedProps> = ({ data, onComplete }) => {
  const [comment, setComment] = React.useState('');
  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (comment.trim().length === 0) {
      return notificationHelper.warn('Ну такоэ...');
    }
    onComplete(comment);
  };
  return (
    <div>
      <p>{`Известно что ${data.date} ты отказался(ась) идти в поход (${data.name}). В чем причина?`}</p>
      <form onSubmit={handleSubmit}>
        <PohInput
          placeholder="Комментарий"
          label="Комментарий"
          type={InputTypes.textarea}
          required
          onChange={setComment}
          value={comment}
        />
        <PohButton type="submit" className="mt-3" block variant={ButtonVariant.Primary}>
          Сохранить
        </PohButton>
      </form>
      <p>
        <small>PS. Сообщение будет появляться пока не напишешь тут свой ответ.</small>
      </p>
    </div>
  );
};

export const requestUncompletedRadishCommentAsync = (
  data: IUncompletedUserRadish,
): Promise<string> =>
  new Promise((res) => {
    showModal({
      title: 'Привет, редиска!',
      children: (clos) => (
        <RadishUncompleted
          data={data}
          onComplete={(comment) => {
            res(comment);
            clos();
          }}
        />
      ),
    });
  });
