import React from 'react';

import styles from './styles.module.less';

interface IWysiwygViewerProps {
  children: string;
}

const WysiwygViewer: React.FC<IWysiwygViewerProps> = ({ children }) => {
  return <div className={styles.wysiwygViewer} dangerouslySetInnerHTML={{ __html: children }} />;
};

export default WysiwygViewer;
