import { get, handleApiError, post } from '@helpers/httpClient';

export const hikingRouteVariantAdd = (id_hiking: number, id_route: number) => {
  return post('/ajax/hiking/route_vars/var_add.php', { id_hiking, id_route }).then<{
    success: boolean;
    id: number;
  }>(handleApiError);
};

export const hikingRouteVariantDelete = (id_hiking: number, id_route: number) => {
  return post('/ajax/hiking/route_vars/var_del.php', { id_hiking, id_route }).then<{
    success: boolean;
  }>(handleApiError);
};

export const hikingRouteVariantVote = (id_hiking: number, id_route: number) => {
  return post('/ajax/hiking/route_vars/var_vote.php', { id_hiking, id_route }).then<{
    success: boolean;
  }>(handleApiError);
};

export interface IHikingRouteVariantDTO {
  date_create: string;
  author_name: string;
  hiking_id: string;
  route_id: string;
  route_name: string;
  route_desc: string;
  route_bounds: string;
  route_preview: string;
  tileUrlTmpl: string;
  isElliptical: string;
  subdomains: string;
  map_name: string;
  map_key: string;
  vote_count: string;
  my_vote: string;
  my: string;
  distance: string;
}

export const getHikingRouteVariants = (id_hiking: number) => {
  return get('/ajax/hiking/route_vars/var_list.php', { id_hiking }).then<IHikingRouteVariantDTO[]>(
    handleApiError,
  );
};
