import { QRCodeSVG } from 'qrcode.react';

import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import { showModal } from '@ui-kit/Modal';

export const qrGenerate = function (d: IHikingData) {
  let link = '';
  link += 'BEGIN:VEVENT\u000d\u000a';
  link += `SUMMARY:${d.name}\u000d\u000a`;
  link += `DTSTART:${d.start.toISOString().substr(0, 19).replace(/[-:]/g, '')}\u000d\u000a`;
  link += `DTEND:${d.finish.toISOString().substr(0, 19).replace(/[-:]/g, '')}\u000d\u000a`;
  link += `DESCRIPTION:${d.desc}\u000d\u000a`;
  link += 'END:VEVENT\u000d\u000a';
  showModal({
    title: 'Отсканируйте QR-код',
    size: 'sm',
    children: <QRCodeSVG value={encodeURI(link)} size={350} />,
  });
};

export default { qrGenerate };
